import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_svg/flutter_svg.dart';import '../../../../../../Core/Utils/Widget/custom_massage.dart';import '../../../../../../Core/Utils/Widget/loading_animation.dart';import '../../domain/repositories/cart_repo_impl.dart';import '../../domain/useCases/cart_use_case.dart';import '../Cubit/Cart/cart_state.dart';import '../../../../../../Config/Assets/image_svg.dart';import '../../../../../../Core/Resources/app_fonts.dart';import '../../../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../ProductsDetails/presentation/components/build_button_add_cart.dart';import '../Cubit/Cart/cart_cubit.dart';class CartScreen extends StatelessWidget {  const CartScreen({super.key});  @override  Widget build(BuildContext context) {    final local = context.local;    return BlocProvider(      create: (context) =>      CartCubit(        GetCartUseCase(          CartRepoImpl(),        ),      )        ..init(),      child: BlocBuilder<CartCubit, CartStates>(        builder: (context, state) {          return Scaffold(            appBar: AppBar(              title: Text(                local.cart,                style: AppTextStyles.h6Bold,              ),              centerTitle: true,            ),            body:state.loading == true? CustomLoadingAnimation(): state.loading == null? Center(                child: Column(                  mainAxisAlignment: MainAxisAlignment.center,                  children: [                    SvgPicture.asset(AppImagesSvg.cartEmpty),                    Text(                      local.massageInCart,                      style: AppTextStyles.bodyMediumBold,                    )                  ],                )):CustomMassage(massage: "items"),            persistentFooterButtons: [              BuildButtonBottomScreen(                nameButton: context.local.BuyNow,                onPressed: () {},                price: state.cartItems?.summary?.grandTotal.toString() ?? "0",              ),            ],          );        },      ),    );  }}